const $=id=>document.getElementById(id);
const configs={leave:{name:'请假说明',icon:'↗',fields:[['date','缺席日期（含年份）','如：20 September 2026'],['reason','请假原因','select']],example:{date:'20 September 2026',reason:'illness'}},grade:{name:'询问评分',icon:'≡',fields:[['assignment','作业或考试名称（英文）','如：Essay 1'],['question','想了解的评分点','select']],example:{assignment:'Essay 1',question:'feedback'}},office:{name:'预约答疑',icon:'◷',fields:[['topic','讨论内容（英文）','如：the research question for my essay'],['availability','可用时间（含日期、时区）','如：22 September 2026, 14:00–16:00 (China Standard Time)']],example:{topic:'the research question for my essay',availability:'22 September 2026, 14:00–16:00 (China Standard Time)'}}};
let current='leave',hasDraft=false;
const choices={reason:[['illness','身体不适'],['personal','个人原因'],['family','家庭事务']],question:[['feedback','了解扣分原因与改进建议'],['rubric','确认评分标准的应用'],['calculation','请老师核对分数计算']]};
function markStale(){if(hasDraft){$('state').textContent='信息已变更，请重新生成';$('feedback').textContent='右侧保留上一份草稿。重新生成会替换你的编辑。';}}
function setScenario(key){current=key;$('scenarios').innerHTML=Object.entries(configs).map(([k,c])=>`<button type="button" class="scenario" data-key="${k}" aria-pressed="${k===key}"><b aria-hidden="true">${c.icon}</b>${c.name}</button>`).join('');$('scenarios').querySelectorAll('button').forEach(b=>b.onclick=()=>setScenario(b.dataset.key));$('dynamic').innerHTML=configs[key].fields.map(([id,label,hint])=>`<label>${label} <span>*</span>${hint==='select'?`<select id="${id}" required>${choices[id].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`:`<input id="${id}" placeholder="${hint}" required maxlength="300">`}</label>`).join('');$('error').textContent='';markStale();}
function generate(){const ids=['student','teacher','course',...configs[current].fields.map(f=>f[0])];if(['sid',...ids].some(id=>!$(id).value.trim())){$('error').textContent='请补齐标有 * 的信息。';return null}const english=ids.filter(id=>/[\u3400-\u9fff]/.test($(id).value));if(english.length){$('error').textContent='姓名、称呼、课程及自定义内容请填写英文，以便生成完整英文邮件。';return null}$('error').textContent='';const v=Object.fromEntries(ids.map(id=>[id,$(id).value.trim()]));const tone=$('tone').value;let subject,request;
if(current==='leave'){subject=`Absence request — ${v.course} — ${v.date}`;const reason={illness:'because I am unwell',personal:'for personal reasons',family:'due to a family matter'}[v.reason];request=`I am writing to let you know that I will be unable to attend ${v.course} on ${v.date} ${reason}. I would like to request permission to be absent.\n\nCould you please let me know how I can catch up on any missed material and whether there are any absence procedures I should follow?`;}
if(current==='grade'){subject=`Question about feedback on ${v.assignment} — ${v.course}`;request=`I am writing to ask about the feedback on ${v.assignment} for ${v.course}.\n\n`+{feedback:'Could you please clarify where I lost marks and how I could improve in future assignments?',rubric:'Could you please explain how the assessment criteria were applied to my work? I would appreciate a clearer understanding of the areas I need to improve.',calculation:'Would you mind checking whether the component marks and the overall total are consistent? I may have misunderstood the calculation and would appreciate your clarification.'}[v.question];}
if(current==='office'){subject=`Office hours appointment request — ${v.course}`;request=`I would like to meet with you during office hours to discuss ${v.topic} for ${v.course}.\n\nI am available on ${v.availability}. Would any time within this window work for you? If not, please let me know an alternative time.`;}
const opening=tone==='formal'?'I hope you are well. ':'';const identity=tone==='concise'?'':`My name is ${v.student}, and I am a student in your ${v.course} class.\n\n`;const thanks=tone==='formal'?'Thank you for your time and consideration.':'Thank you for your help.';const sid=$('sid').value.trim();const body=`Dear ${v.teacher},\n\n${opening}${identity}${request}\n\n${thanks}\n\n${tone==='formal'?'Kind regards':'Best regards'},\n${v.student}${sid?'\nStudent ID: '+sid:''}`;
$('subject').value=subject;$('body').value=body;$('empty').hidden=true;$('draft').hidden=false;$('state').textContent='草稿已生成';$('feedback').textContent='可以直接编辑主题与正文。';document.querySelectorAll('.checklist input').forEach(x=>x.checked=false);hasDraft=true;return {subject,body};}
$('form').onsubmit=e=>{e.preventDefault();generate()};$('form').addEventListener('input',markStale);$('form').addEventListener('change',markStale);
$('example').onclick=()=>{Object.entries({student:'Yutong Chen',teacher:'Dr. Smith',course:'ECON101',sid:'20260001',...configs[current].example}).forEach(([id,v])=>$(id).value=v);markStale();$('error').textContent='已填入虚构示例，请替换为你的真实信息。'};
function fullText(){return `Subject: ${$('subject').value}\n\n${$('body').value}`}
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(fullText());$('feedback').textContent='已复制主题和正文。请在邮箱中确认后发送。'}catch{$('feedback').textContent='复制受浏览器限制，请手动选中正文复制，或下载草稿。'}};
$('download').onclick=()=>{const u=URL.createObjectURL(new Blob([fullText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='dear-prof-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('feedback').textContent='草稿已下载。'};
setScenario(current);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'generate_email_draft',description:'Generate an editable English email draft from the currently filled visible form. Does not send email.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');const draft=generate();if(!draft)throw new Error($('error').textContent);return draft}})).catch(()=>{});}catch{}}
